window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a6aa98e38ea19ba6"]={"versions": [{"id": "FIG-a6aa98e38ea19ba6", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Teilablaufs innerhalb der E2E-Bibliothek (AUTOSAR Classic/Adaptive Platform). Das Diagramm detailliert den Teilschritt „Read CRC“ der Prüffunktion <code>E2E_P04Check()</code>, welche empfangene Nutzdaten nach den Vorgaben des E2E-Profils 4 verifiziert.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm deklariert den Kontext über das Aktivitäts-Symbol <code>E2E_P04Check()</code>. Zentrales Element ist die Aktionsbox <code>Copy bytes Data[Offset+8...Offset+11] using big Endian order on 4-byte local variable ReceivedCRC</code>. Die Interaktion erfolgt auf dem übergebenen Byte-Array <code>Data</code> unter Verwendung eines offsetspezifischen Indexbereichs sowie einer lokalen 4-Byte-Ganzzahlvariable <code>ReceivedCRC</code> (32 Bit, passend für CRC-32 von E2E Profile 4).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Sequenz startet am Initialknoten und führt über eine unbedingte Transition zur Aktion <code>Copy bytes Data[Offset+8...Offset+11] using big Endian order on 4-byte local variable ReceivedCRC</code>. Hierbei werden vier aufeinanderfolgende Bytes ab der Position <code>Offset + 8</code> bis <code>Offset + 11</code> in Big-Endian-Byte-Reihenfolge (Most Significant Byte zuerst) in die lokale 32-Bit-Variable <code>ReceivedCRC</code> eingelesen. Nach Abschluss des Lesevorgangs geht der Kontrollfluss über einen gerichteten Kontrollflusskante direkt in den Aktivitätsendknoten über.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß Anforderung PRS_E2E_00360 ist das Verhalten dieses Teilschritts normativ verbindlich für die Implementierung von <code>E2E_P04Check()</code>. Entwickler müssen sicherstellen, dass das Datenfeld <code>Data</code> mindestens die Länge <code>Offset + 12</code> aufweist, um Out-of-Bounds-Zugriffe zu vermeiden, und dass das Auslesen plattformunabhängig strikt in Big-Endian-Reihenfolge in die lokale 32-Bit-Variable konvertiert wird, bevor nachfolgende Prüfschritte (Berechnung und Vergleich) ausgeführt werden.</p>"}, {"id": "FIG-2d976b3044256e00", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Teilablaufs innerhalb der E2E-Bibliothek (AUTOSAR Classic/Adaptive Platform). Das Diagramm detailliert den Teilschritt „Read CRC“ der Prüffunktion <code>E2E_P04Check()</code>, welche empfangene Nutzdaten nach den Vorgaben des E2E-Profils 4 verifiziert.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm deklariert den Kontext über das Aktivitäts-Symbol <code>E2E_P04Check()</code>. Zentrales Element ist die Aktionsbox <code>Copy bytes Data[Offset+8...Offset+11] using big Endian order on 4-byte local variable ReceivedCRC</code>. Die Interaktion erfolgt auf dem übergebenen Byte-Array <code>Data</code> unter Verwendung eines offsetspezifischen Indexbereichs sowie einer lokalen 4-Byte-Ganzzahlvariable <code>ReceivedCRC</code> (32 Bit, passend für CRC-32 von E2E Profile 4).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Sequenz startet am Initialknoten und führt über eine unbedingte Transition zur Aktion <code>Copy bytes Data[Offset+8...Offset+11] using big Endian order on 4-byte local variable ReceivedCRC</code>. Hierbei werden vier aufeinanderfolgende Bytes ab der Position <code>Offset + 8</code> bis <code>Offset + 11</code> in Big-Endian-Byte-Reihenfolge (Most Significant Byte zuerst) in die lokale 32-Bit-Variable <code>ReceivedCRC</code> eingelesen. Nach Abschluss des Lesevorgangs geht der Kontrollfluss über einen gerichteten Kontrollflusskante direkt in den Aktivitätsendknoten über.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß Anforderung PRS_E2E_00360 ist das Verhalten dieses Teilschritts normativ verbindlich für die Implementierung von <code>E2E_P04Check()</code>. Entwickler müssen sicherstellen, dass das Datenfeld <code>Data</code> mindestens die Länge <code>Offset + 12</code> aufweist, um Out-of-Bounds-Zugriffe zu vermeiden, und dass das Auslesen plattformunabhängig strikt in Big-Endian-Reihenfolge in die lokale 32-Bit-Variable konvertiert wird, bevor nachfolgende Prüfschritte (Berechnung und Vergleich) ausgeführt werden.</p>"}, {"id": "FIG-d4aa5e049b1f3ba8", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses innerhalb der AUTOSAR E2E-Bibliothek (End-to-End Communication Protection), spezifisch eingebettet in die Prüffunktion <code>E2E_P44Check()</code> des E2E-Profils 44 (PRS_E2EProtocol). Das Diagramm detailliert den elementaren Teilschritt „Read CRC“ beim Empfang und der Validierung von Datenstrukturen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Kontext / Aufrufende Entität: Funktion <code>E2E_P44Check()</code> (gekennzeichnet über ein Subaktivitäts-/Konnektorsymbol).\n</li><li>Datenstrukturen &amp; Variablen:\n<ul class=\"fig-list\"><li>Eingangsdaten-Array <code>Data[]</code> (Nutzdaten-/Serialisierungsbuffer).\n</li><li>Konfigurationsparameter / Indexversatz <code>Offset</code> (Byte-Offset des E2E-Headers im Datenstrom).\n</li><li>Lokale 4-Byte-Variable <code>ReceivedCRC</code> (Datentyp korrespondierend zu <code>uint32</code>) zur Zwischenspeicherung der extrahierten Prüfsumme.\n</li></ul>\n</li><li>Aktionen: Ein einzelner Aktionsknoten zur Bytekopie und Bytereihenfolgekonvertierung (<code>Copy bytes Data[Offset+8...Offset+11] using big Endian order on 4-byte local variable ReceivedCRC</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt über den Initialknoten (Startknoten) der Aktivität.\n</li><li>Unbedingter Übergang (Control Flow) auf die Aktion zur CRC-Extraktion.\n</li><li>Ausführung der Aktion: Vier aufeinanderfolgende Bytes an den Positionen <code>Data[Offset+8]</code> bis <code>Data[Offset+11]</code> werden unter Berücksichtigung der Big-Endian-Byte-Reihenfolge (Most Significant Byte zuerst) in die lokale 32-Bit-Variable <code>ReceivedCRC</code> kopiert.\n</li><li>Unbedingter Kontrollfluss zum Aktivitätsendknoten (Activity Final Node).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Aktivität spezifiziert verbindlich das Layout und das Extraktionsverfahren der empfangenen Prüfsumme für das E2E-Profil 44. Bei der Implementierung ist sicherzustellen, dass:</p>\n<ul class=\"fig-list\"><li>Die CRC als 32-Bit-Wert an Offset + 8 Byte bis Offset + 11 Byte relativ zum konfigurierten Header-Offset liegt.\n</li><li>Unabhängig von der Host-CPU-Architektur (Little-Endian oder Big-Endian) das Einlesen streng nach Big-Endian-Konvention (<code>Data[Offset+8]</code> als MSB, <code>Data[Offset+11]</code> als LSB) erfolgt.\n</li><li>Vor dem lesenden Zugriff sichergestellt ist, dass der Puffer <code>Data[]</code> mindestens die Länge <code>Offset + 12</code> aufweist, um Speicherzugriffsverletzungen zu vermeiden.\n</li></ul>"}], "trans": [{"from": "FIG-a6aa98e38ea19ba6", "to": "FIG-2d976b3044256e00", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
